style.css:
/* Set up the body with the background image */
body {
  font-family: 'Arial', sans-serif;
  margin: 0;
  padding: 0;
  height: 100vh;
  background-image: url('https://wallpapercat.com/w/full/b/2/d/647875-1920x1080-desktop-full-hd-tyler-the-creator-background-image.jpg');
  background-size: cover; /* Make sure the background covers the entire screen */
  background-position: center;
  background-attachment: fixed; /* Make the background stay in place when scrolling */
  display: flex;
  justify-content: center;
  align-items: center;
  color: white;
}

/* Style for the text */
h1 {
  font-size: 3rem;
  letter-spacing: 3px;
  text-transform: uppercase;
  text-shadow: 2px 2px 8px rgba(0, 0, 0, 0.6), 0 0 25px rgba(255, 0, 0, 0.4);
  background-image: linear-gradient(to right, #ff7e5f, #feb47b);
  -webkit-background-clip: text;
  background-clip: text;
  animation: glowingText 1.5s infinite alternate;
}

/* Glowing effect animation */
@keyframes glowingText {
  0% {
    text-shadow: 0 0 10px #fff, 0 0 20px #ff0000, 0 0 30px #ff0000;
  }
  100% {
    text-shadow: 0 0 15px #fff, 0 0 30px #ff0000, 0 0 45px #ff0000;
  }
}
